"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[884],{5454(e,n,t){t.r(n),t.d(n,{assets:()=>d,contentTitle:()=>c,default:()=>h,frontMatter:()=>l,metadata:()=>r,toc:()=>p});const r=JSON.parse('{"id":"part3-agent-protocols/mcp-enterprise-pattern","title":"MCP Enterprise Pattern: Authentication and Salesforce Integration","description":"With Authentication and MCP Primitives: Tools / Resources / Prompts","source":"@site/docs/part3-agent-protocols/03-mcp-enterprise-pattern.mdx","sourceDirName":"part3-agent-protocols","slug":"/part3-agent-protocols/03-mcp-enterprise-pattern","permalink":"/tutorials/part3-agent-protocols/03-mcp-enterprise-pattern","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":3,"frontMatter":{"title":"MCP Enterprise Pattern: Authentication and Salesforce Integration","slug":"/part3-agent-protocols/03-mcp-enterprise-pattern","description":"With Authentication and MCP Primitives: Tools / Resources / Prompts","sidebar_label":"3. MCP enterprise pattern","pagination_label":"3. MCP enterprise pattern","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"2. MCP discovery, remote transport, and auth","permalink":"/tutorials/part3-agent-protocols/02-mcp-discovery-remote-auth"},"next":{"title":"4. MCP protocol evolution","permalink":"/tutorials/part3-agent-protocols/04-mcp-2025-update"}}');var s=t(4848),o=t(8453),a=t(8172);const i=JSON.parse('{"sourcePath":"part3-agent-protocols/03-mcp-enterprise-pattern.html","route":"/part3-agent-protocols/03-mcp-enterprise-pattern","kind":"chapter","partId":"part3","partLabel":"Part III - Agent Protocols & Integration","accent":"violet","heading":"Enterprise Example: FastAPI \u2192 MCP Server \u2192 Salesforce","title":"MCP Enterprise Pattern: Authentication and Salesforce Integration","description":"With Authentication and MCP Primitives: Tools / Resources / Prompts","readingMinutes":6,"bodyClass":"","normalizeMath":false,"toc":[{"id":"part-a-mcp-salesforce-server","label":"Part A \u2014 MCP Salesforce Server"},{"id":"part-b-fastapi-host-endpoint","label":"Part B \u2014 FastAPI Host Endpoint"},{"id":"what-changed-the-auth-story","label":"What Changed: The \\"Auth Story\\""},{"id":"environment-variables-required","label":"Environment Variables Required"},{"id":"summary-why-this-architecture-matters","label":"Summary: Why This Architecture Matters"}],"html":"<div class=\\"container\\">\\n        \\n        <p style=\\"font-size: 1.1em; color: #555; margin-bottom: 30px;\\">\\n            <strong>With Authentication and MCP Primitives: Tools / Resources / Prompts</strong>\\n        </p>\\n\\n        <div class=\\"tr-update\\">\\n            <strong>Current implementation boundary</strong>\\n            The architecture and authorization boundaries are protocol-version\\n            independent. For MCP <code>2026-07-28</code>, deploy the HTTP\\n            server statelessly and use client/server releases that explicitly\\n            support that version. Some high-level <code>fastmcp</code> APIs\\n            shown here can also target the 2025 protocol family; do not assume\\n            a library class name proves wire-level compatibility.\\n        </div>\\n\\n        <div class=\\"auth-boundaries\\">\\n            <h3 id=\\"three-separate-auth-boundaries-in-your-bank-style-setup\\">Three Separate Auth Boundaries in Your Bank-Style Setup</h3>\\n            \\n            <div class=\\"auth-step\\">\\n                <h4>1. User \u2192 FastAPI (your app auth)</h4>\\n                <p>\\n                    User logs in with <strong>Google Workspace (OIDC)</strong>. React calls FastAPI with \\n                    <code class=\\"inline-code\\">Authorization: Bearer &lt;user_access_token&gt;</code>.\\n                </p>\\n            </div>\\n\\n            <div class=\\"auth-step\\">\\n                <h4>2. FastAPI \u2192 MCP server (service-to-service auth)\\n                    <span class=\\"status added\\">internal boundary</span>\\n                </h4>\\n                <p>\\n                    Your FastAPI backend calls the MCP server using a <strong>separate internal Bearer token</strong> \\n                    (or OAuth/JWT/mTLS in real prod). This prevents \\"anyone who can reach the MCP URL\\" from using it.\\n                </p>\\n            </div>\\n\\n            <div class=\\"auth-step\\">\\n                <h4>3. MCP server \u2192 Salesforce (downstream service auth)</h4>\\n                <p>\\n                    MCP server authenticates to Salesforce as an <strong>integration identity</strong> (service-level) \\n                    using <strong>OAuth JWT Bearer flow</strong>.\\n                </p>\\n            </div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"part-a-mcp-salesforce-server\\">Part A \u2014 MCP Salesforce Server</h2>\\n            <p><strong>Components:</strong> Auth Middleware + Resource + Prompt + Tool</p>\\n\\n            <div class=\\"info-box\\">\\n                <h4>FastMCP Features Used:</h4>\\n                <ul>\\n                    <li><strong>Middleware:</strong> Intercept requests for authentication</li>\\n                    <li><strong>Resources:</strong> Read-only URIs for policies/schemas/guardrails</li>\\n                    <li><strong>Prompts:</strong> Server-defined templates to guide clients/agents consistently</li>\\n                    <li><strong>Tools:</strong> Executable actions that interact with external systems</li>\\n                </ul>\\n            </div>\\n\\n            <p><strong>Save as:</strong> <code class=\\"inline-code\\">mcp_salesforce_server.py</code></p>\\n\\n            <div class=\\"code-block\\">\\n                <div class=\\"code-header\\">mcp_salesforce_server.py</div>\\n                <pre><code class=\\"language-python\\"># pip install fastmcp httpx PyJWT cryptography cachetools\\n\\nimport os\\nimport re\\nimport time\\nfrom typing import Any, Dict, Optional, TypedDict\\n\\nimport httpx\\nimport jwt\\nfrom cachetools import TTLCache\\n\\nfrom fastmcp import FastMCP\\nfrom fastmcp.exceptions import ToolError\\nfrom fastmcp.server.dependencies import get_http_headers\\nfrom fastmcp.server.middleware import Middleware, MiddlewareContext\\n\\nmcp = FastMCP(\\n    \\"DocQA-Salesforce-MCP\\",\\n    stateless_http=True,\\n    json_response=True,\\n)\\n\\n# -----------------------------------------------------------------------------\\n# 1) SERVICE-TO-SERVICE AUTH (FastAPI -&gt; MCP)\\n#    MCP server requires: Authorization: Bearer &lt;MCP_SERVICE_TOKEN&gt;\\n# -----------------------------------------------------------------------------\\nMCP_SERVICE_TOKEN = os.environ[\\"MCP_SERVICE_TOKEN\\"]\\n\\nclass ServiceAuthMiddleware(Middleware):\\n    async def on_request(self, context: MiddlewareContext, call_next):\\n        # Runs for MCP \\"request\\" messages (list tools, call tool, read resource, get prompt, etc.)\\n        headers = get_http_headers()\\n        auth = headers.get(\\"authorization\\") or headers.get(\\"Authorization\\")\\n\\n        if not auth or not auth.startswith(\\"Bearer \\"):\\n            raise ToolError(\\"Unauthorized: missing Bearer token to call MCP server\\")\\n\\n        token = auth.removeprefix(\\"Bearer \\").strip()\\n        if token != MCP_SERVICE_TOKEN:\\n            raise ToolError(\\"Unauthorized: invalid MCP service token\\")\\n\\n        return await call_next(context)\\n\\nmcp.add_middleware(ServiceAuthMiddleware())  # FastMCP middleware registration\\n\\n# -----------------------------------------------------------------------------\\n# 2) SALESFORCE SERVICE-LEVEL AUTH (MCP -&gt; Salesforce)\\n#    OAuth JWT Bearer flow to get access_token.\\n# -----------------------------------------------------------------------------\\nSF_LOGIN_URL   = os.environ.get(\\"SF_LOGIN_URL\\", \\"https://login.salesforce.com\\").rstrip(\\"/\\")\\nSF_CLIENT_ID   = os.environ[\\"SF_CLIENT_ID\\"]           # Connected App consumer key\\nSF_USERNAME    = os.environ[\\"SF_USERNAME\\"]            # Integration user username\\nSF_PRIVATE_KEY = os.environ[\\"SF_PRIVATE_KEY_PEM\\"]     # PEM private key\\nSF_API_VERSION = os.environ.get(\\"SF_API_VERSION\\", \\"v67.0\\")  # Summer \'26; configure and test explicitly\\n\\n_token_cache: TTLCache[str, Dict[str, Any]] = TTLCache(maxsize=1, ttl=14 * 60)  # ~14 min cache\\n\\ndef _build_jwt_assertion() -&gt; str:\\n    now = int(time.time())\\n    payload = {\\n        \\"iss\\": SF_CLIENT_ID,\\n        \\"sub\\": SF_USERNAME,\\n        \\"aud\\": SF_LOGIN_URL,\\n        \\"exp\\": now + 180,  # short-lived assertion\\n    }\\n    return jwt.encode(payload, SF_PRIVATE_KEY, algorithm=\\"RS256\\")\\n\\nasync def _get_salesforce_token() -&gt; tuple[str, str]:\\n    cached = _token_cache.get(\\"sf_token\\")\\n    if cached:\\n        return cached[\\"access_token\\"], cached[\\"instance_url\\"]\\n\\n    token_url = f\\"{SF_LOGIN_URL}/services/oauth2/token\\"\\n    data = {\\n        \\"grant_type\\": \\"urn:ietf:params:oauth:grant-type:jwt-bearer\\",\\n        \\"assertion\\": _build_jwt_assertion(),\\n    }\\n\\n    async with httpx.AsyncClient(timeout=10) as client:\\n        r = await client.post(token_url, data=data)\\n        if r.status_code != 200:\\n            raise RuntimeError(f\\"Salesforce token error: {r.status_code} {r.text}\\")\\n        tok = r.json()\\n\\n    _token_cache[\\"sf_token\\"] = {\\n        \\"access_token\\": tok[\\"access_token\\"],\\n        \\"instance_url\\": tok[\\"instance_url\\"],\\n    }\\n    return tok[\\"access_token\\"], tok[\\"instance_url\\"]\\n\\n# -----------------------------------------------------------------------------\\n# 3) RESOURCE: publish a \\"bank-safe SOQL policy\\" as read-only context\\n# -----------------------------------------------------------------------------\\n@mcp.resource(\\"resource://salesforce/soql_policy\\")\\ndef soql_policy() -&gt; str:\\n\\t    return (\\n\\t        \\"BANK POLICY:\\\\n\\"\\n\\t        \\"- Only SELECT queries\\\\n\\"\\n\\t        \\"- LIMIT required (&lt;= 50)\\\\n\\"\\n\\t        \\"- No write keywords (INSERT/UPDATE/DELETE/UPSERT/MERGE)\\\\n\\"\\n\\t        \\"- Require allowlisted objects and fields in production\\\\n\\"\\n\\t    )\\n\\n# -----------------------------------------------------------------------------\\n# 4) PROMPT: a reusable instruction template clients/agents can fetch\\n# -----------------------------------------------------------------------------\\n@mcp.prompt\\ndef salesforce_safe_query_prompt() -&gt; str:\\n    return (\\n        \\"You are generating Salesforce SOQL for a banking environment.\\\\n\\"\\n        \\"Follow the SOQL policy from resource://salesforce/soql_policy.\\\\n\\"\\n        \\"Always include LIMIT &lt;= 50. Only SELECT.\\\\n\\"\\n    )\\n\\n# -----------------------------------------------------------------------------\\n# 5) TOOL: execute SOQL (after validation) via Salesforce Query REST endpoint\\n#    /services/data/vXX.X/query?q=&lt;soql&gt;\\n# -----------------------------------------------------------------------------\\ndef _validate_soql_bank_safe(soql: str) -&gt; None:\\n    s = soql.strip()\\n    if not re.match(r\\"(?is)^select\\\\s\\", s):\\n        raise ValueError(\\"Only SELECT queries are allowed\\")\\n\\n    if re.search(r\\"(?is)\\\\b(insert|update|delete|upsert|merge|drop)\\\\b\\", s):\\n        raise ValueError(\\"Write operations are not allowed\\")\\n\\n    m = re.search(r\\"(?is)\\\\blimit\\\\s+(\\\\d+)\\\\b\\", s)\\n    if not m:\\n        raise ValueError(\\"LIMIT is required\\")\\n    if int(m.group(1)) &gt; 50:\\n        raise ValueError(\\"LIMIT too high (max 50)\\")\\n\\nasync def _sf_query(instance_url: str, access_token: str, soql: str) -&gt; Dict[str, Any]:\\n    url = f\\"{instance_url}/services/data/{SF_API_VERSION}/query\\"\\n    headers = {\\"Authorization\\": f\\"Bearer {access_token}\\"}\\n\\n    async with httpx.AsyncClient(timeout=15) as client:\\n        r = await client.get(url, headers=headers, params={\\"q\\": soql})\\n        if r.status_code == 401:\\n            # token expired/invalid -&gt; clear cache and retry once\\n            _token_cache.pop(\\"sf_token\\", None)\\n            access_token, instance_url = await _get_salesforce_token()\\n            headers[\\"Authorization\\"] = f\\"Bearer {access_token}\\"\\n            r = await client.get(url, headers=headers, params={\\"q\\": soql})\\n\\n        if r.status_code != 200:\\n            raise RuntimeError(f\\"Query error: {r.status_code} {r.text}\\")\\n\\n        return r.json()\\n\\n@mcp.tool()\\nasync def sf_execute_soql(soql: str) -&gt; Dict[str, Any]:\\n    \\"\\"\\"\\n    Executes SOQL under the integration user\'s permissions.\\n    \\"\\"\\"\\n    _validate_soql_bank_safe(soql)\\n    access_token, instance_url = await _get_salesforce_token()\\n    return await _sf_query(instance_url, access_token, soql)\\n\\nif __name__ == \\"__main__\\":\\n    # Streamable HTTP is the common production transport.\\n    mcp.run(transport=\\"streamable-http\\")</code></pre>\\n            </div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"part-b-fastapi-host-endpoint\\">Part B \u2014 FastAPI Host Endpoint</h2>\\n            <p><strong>Calls MCP with Service Authentication</strong></p>\\n\\n            <div class=\\"info-box\\">\\n                <h4>Key Feature:</h4>\\n                <p>\\n                    FastMCP\'s <strong>Streamable HTTP client transport</strong> supports custom headers \\n                    (or a BearerAuth helper) for service-to-service authentication.\\n                </p>\\n            </div>\\n\\n            <p><strong>Save as:</strong> <code class=\\"inline-code\\">main.py</code></p>\\n\\n            <div class=\\"code-block\\">\\n                <div class=\\"code-header\\">main.py</div>\\n                <pre><code class=\\"language-python\\"># pip install fastapi uvicorn fastmcp pydantic\\n\\nimport os\\nfrom fastapi import FastAPI, Depends, HTTPException\\nfrom pydantic import BaseModel\\n\\nfrom fastmcp import Client\\nfrom fastmcp.client.transports import StreamableHttpTransport\\n\\napp = FastAPI()\\n\\nMCP_SF_URL = os.environ[\\"MCP_SF_URL\\"]                  # e.g. https://mcp-salesforce.internal/mcp\\nMCP_SERVICE_TOKEN = os.environ[\\"MCP_SERVICE_TOKEN\\"]    # short-lived OAuth access token from client credentials/token exchange\\n\\nclass SoqlReq(BaseModel):\\n    soql: str\\n\\nasync def get_identity():\\n    # Production: verify OIDC Bearer token, map groups/roles, and return claims.\\n    return {\\"email\\": \\"alice@bank.com\\", \\"roles\\": [\\"salesforce.query.read\\"]}\\n\\n@app.post(\\"/admin/salesforce/query\\")\\nasync def admin_salesforce_query(req: SoqlReq, ident=Depends(get_identity)):\\n    # Bank rule: free-form query text is privileged and should usually be\\n    # replaced by named, parameterized tools. If kept, gate it by role/scope.\\n    if \\"salesforce.query.read\\" not in ident.get(\\"roles\\", []):\\n        raise HTTPException(status_code=403, detail=\\"Missing salesforce.query.read\\")\\n\\n    # Service-to-service auth to MCP server (NOT the end-user token)\\n    transport = StreamableHttpTransport(\\n        url=MCP_SF_URL,\\n        headers={\\"Authorization\\": f\\"Bearer {MCP_SERVICE_TOKEN}\\"},\\n    )\\n    mcp_client = Client(transport)\\n\\n    async with mcp_client:\\n        # Optional: read policy/prompt for debugging or to feed an agent\\n        policy = await mcp_client.read_resource(\\"resource://salesforce/soql_policy\\")\\n        prompt = await mcp_client.get_prompt(\\"salesforce_safe_query_prompt\\")\\n\\n        # Actual tool call\\n        res = await mcp_client.call_tool(\\"sf_execute_soql\\", {\\"soql\\": req.soql})\\n        return {\\n            \\"policy\\": policy.content,   # what the server says is allowed\\n            \\"prompt\\": prompt.messages,  # how the server wants queries generated\\n            \\"result\\": res,\\n        }</code></pre>\\n            </div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"what-changed-the-auth-story\\">What Changed: The \\"Auth Story\\"</h2>\\n\\n            <div class=\\"key-changes\\">\\n                <h3 id=\\"key-security-improvements\\">Key Security Improvements</h3>\\n                <ul>\\n                    <li>\\n                        <strong>FastAPI doesn\'t just \\"call the MCP URL.\\"</strong> \\n                        It must present an MCP service token (or OAuth/JWT/mTLS in stricter setups).\\n                    </li>\\n                    <li>\\n                        <strong>The MCP server enforces that token in middleware</strong> \\n                        before allowing any MCP operation (tools/resources/prompts/listing).\\n                    </li>\\n                    <li>\\n                        <strong>Only after that does the MCP tool do Salesforce service-level auth</strong> \\n                        (JWT Bearer) and run SOQL via Salesforce\'s Query REST endpoint.\\n                    </li>\\n                </ul>\\n            </div>\\n\\n            <div class=\\"architecture-note\\">\\n                <h3 style=\\"color: #e74c3c; margin-bottom: 20px;\\" id=\\"authentication-flow\\">Authentication Flow</h3>\\n                <p><strong>User</strong> (Google OIDC)</p>\\n                <div class=\\"flow-arrow\\">\u2193</div>\\n                <p><strong>FastAPI</strong> (User token validated)</p>\\n                <div class=\\"flow-arrow\\">\u2193</div>\\n                <p><strong>MCP Server</strong> (Service token validated in middleware)</p>\\n                <div class=\\"flow-arrow\\">\u2193</div>\\n                <p><strong>Salesforce</strong> (OAuth JWT Bearer flow)</p>\\n            </div>\\n\\n            <div class=\\"warning-box\\">\\n                <h4>Next Level Security:</h4>\\n                <p>\\n                    To tighten the bank-safe boundary, the client must never\\n                    send arbitrary SOQL. It sends only validated\\n                    <strong>parameters</strong>, such as an email address,\\n                    while the MCP server constructs a\\n                    <strong>fixed allowlisted query</strong> internally.\\n                </p>\\n            </div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"environment-variables-required\\">Environment Variables Required</h2>\\n\\n            <div class=\\"highlight-box\\">\\n                <h4>MCP Server (mcp_salesforce_server.py):</h4>\\n                <ul>\\n                    <li><code class=\\"inline-code\\">MCP_SERVICE_TOKEN</code> - Short-lived OAuth token for FastAPI \u2192 MCP auth</li>\\n                    <li><code class=\\"inline-code\\">SF_CLIENT_ID</code> - Salesforce Connected App consumer key</li>\\n                    <li><code class=\\"inline-code\\">SF_USERNAME</code> - Integration user username</li>\\n                    <li><code class=\\"inline-code\\">SF_PRIVATE_KEY_PEM</code> - PEM private key for JWT signing</li>\\n                    <li><code class=\\"inline-code\\">SF_LOGIN_URL</code> - (Optional) Default: https://login.salesforce.com</li>\\n                    <li><code class=\\"inline-code\\">SF_API_VERSION</code> - (Optional) Example default: v67.0 (Summer \'26); pin a version supported by your org and regression-test upgrades</li>\\n                </ul>\\n            </div>\\n\\n            <div class=\\"highlight-box\\" style=\\"margin-top: 20px;\\">\\n                <h4>FastAPI Host (main.py):</h4>\\n                <ul>\\n                    <li><code class=\\"inline-code\\">MCP_SF_URL</code> - MCP server URL (e.g., http://mcp-salesforce.internal/mcp)</li>\\n                    <li><code class=\\"inline-code\\">MCP_SERVICE_TOKEN</code> - Short-lived OAuth token, preferably obtained at startup or per request from the IdP</li>\\n                </ul>\\n            </div>\\n        </div>\\n\\n        <hr class=\\"divider\\">\\n\\n        <div class=\\"section\\">\\n            <h2 id=\\"summary-why-this-architecture-matters\\">Summary: Why This Architecture Matters</h2>\\n            \\n            <div class=\\"info-box\\">\\n                <h4>Defense in Depth:</h4>\\n                <ol class=\\"numbered-list\\">\\n                    <li><strong>User Authentication:</strong> Validates end-user identity via Google OIDC</li>\\n                    <li><strong>Service Authentication:</strong> Prevents unauthorized access to MCP server</li>\\n                    <li><strong>Downstream Authentication:</strong> Secures integration with Salesforce</li>\\n                    <li><strong>Query Validation:</strong> Enforces bank-safe SOQL policies at MCP layer</li>\\n                    <li><strong>Resource Policies:</strong> Provides read-only context for LLM agents</li>\\n                    <li><strong>Prompt Templates:</strong> Standardizes agent behavior across clients</li>\\n                </ol>\\n            </div>\\n\\n            <div class=\\"highlight-box\\" style=\\"margin-top: 20px;\\">\\n                <p><strong>Result:</strong> A secure, auditable system where each layer has its own authentication \\n                boundary and the MCP server acts as a controlled gateway to sensitive operations.</p>\\n            </div>\\n\\n            <p><strong>Official references:</strong>\\n                <a href=\\"https://modelcontextprotocol.io/specification/2026-07-28\\">MCP 2026-07-28 specification</a> \xb7\\n                <a href=\\"https://developer.salesforce.com/blogs/2026/06/the-salesforce-developers-guide-to-the-summer-26-release\\">Salesforce Summer \'26 / API 67.0</a> \xb7\\n                <a href=\\"https://developer.salesforce.com/docs/platform/connect-rest-api/guide/intro_api_eol.html\\">Salesforce API end-of-life policy</a>\\n            </p>\\n        </div>\\n    </div>"}'),l={title:"MCP Enterprise Pattern: Authentication and Salesforce Integration",slug:"/part3-agent-protocols/03-mcp-enterprise-pattern",description:"With Authentication and MCP Primitives: Tools / Resources / Prompts",sidebar_label:"3. MCP enterprise pattern",pagination_label:"3. MCP enterprise pattern",hide_title:!0,hide_table_of_contents:!0},c=void 0,d={},p=[];function u(e){return(0,s.jsx)(a.A,{content:i})}function h(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(u,{...e})}):u()}}}]);